# Generated by build.py from recipe.yml for recipe http-retry-until-the-server-is-up. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'start-late.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts curl first and surl two seconds later, as a test that starts both at once may,`n# then stops surl once curl is done. Usage: sh start-late.sh <port> [curl options]`nport=`$1; shift`ncurl `"`$@`" `"http://127.0.0.1:`$port/hello.txt`" > fetched.txt &`nclient=`$!`nsleep 2`nsurl --directory site `"http://127.0.0.1:`$port/`" > surl.log 2>&1 &`nserver=`$!`nwait `"`$client`"`nstatus=`$?`nkill `"`$server`"`ncat fetched.txt`nexit `$status`n")
sh start-late.sh 8080 --no-progress-meter --retry 5 --retry-connrefused --retry-delay 1 -w "%{num_retries}\n"
